sys_variable_value.value:
(function execute(inputs, outputs) {
    var amountBRL = parseFloat(inputs.spending_reais);

    var r = new sn_ws.RESTMessageV2('FreeCurrencyAPI', 'Get USD rate');
    var response = r.execute();
    var body = response.getBody();
    var parsed = JSON.parse(body);

    var rate = parsed.data.USD;
    var converted = amountBRL * rate;

    outputs.spending_dollars = converted.toFixed(2);
})(inputs, outputs);

